import { canonicalSha256 } from '../core/canonical-json.mjs';
export function anchorFindings({findings,files}){const accepted=[];const rejected=[];for(const finding of findings??[]){const file=files?.[finding.file];if(!file){rejected.push({...finding,reason:'file-not-found'});continue;}if(!Number.isInteger(finding.line)||finding.line<1||finding.line>file.lines.length){rejected.push({...finding,reason:'line-out-of-range'});continue;}const lineText=file.lines[finding.line-1];if(finding.evidenceText&&!lineText.includes(finding.evidenceText)){rejected.push({...finding,reason:'evidence-text-mismatch'});continue;}accepted.push({...finding,anchor:{file:finding.file,line:finding.line,fileSha256:file.sha256,lineSha256:canonicalSha256(lineText),lineText}});}const payload={accepted,rejected};return Object.freeze({...payload,anchorReceiptSha256:canonicalSha256(payload)});}
